<?php
declare(strict_types=1);require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/reminder.php';requireRole(1,2,4);$role=currentRoleId();$unit=(int)($_SESSION['unit_id']??0);if($role===2&& !$unit){http_response_code(403);exit('Unit kerja belum ditetapkan.');}$sql='SELECT v.* FROM view_jadwal_pemusnahan v INNER JOIN arsip a ON a.arsip_id=v.arsip_id WHERE 1=1';$p=[];if($role===2){$sql.=' AND a.unit_id=:u';$p['u']=$unit;}$sql.=' ORDER BY v.tanggal_jatuh_tempo';$s=$pdo->prepare($sql);$s->execute($p);$items=$s->fetchAll();?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?php require __DIR__.'/includes/favicon.php';?><link rel="stylesheet" href="assets/css/auth.css"><title>Jadwal Pemusnahan</title></head><body class="dashboard-body"><main class="admin-content"><section class="panel"><h2>Jadwal Pemusnahan</h2><div class="table-wrap"><table><thead><tr><th>Registrasi</th><th>Unit</th><th>Jatuh Tempo</th><th>Status</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=e($x['no_registrasi'])?></td><td><?=e($x['nama_unit'])?></td><td><?=e($x['tanggal_jatuh_tempo'])?></td><td><?=e($x['status_jadwal'])?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="4">Belum ada jadwal pemusnahan.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>